#!/usr/bin/env bash
# SPDX-License-Identifier: 0BSD
# Provenance: original pcrec-memory-functions text (lane r15b, R-15).
#
# memfn/tests/run_g2_gate.sh — G2's GATE FAMILY ALONE: the §15.5 composite
# (gate_one) and R-15's landmark sites (landmark_one: the gate whose ret_pred
# is its one byte, and that shape's near-misses), generated by
# `g2_gen --gate-only 1`, rendered through the kit, compiled and run on G2's
# subjects against G2's own reference (g2/g2_ref.c), then once more under
# ASan+UBSan. It is the section standalone, for a lane or a mech row whose
# box budget is not a whole `make test-memfn-g2`; that target runs the same
# sites inside its own (larger) space and stays the verdict.
#
#   memfn/tests/run_g2_gate.sh [--seed N] [--keep]
#
# Judged here (floors are LITERALS, sharing no source with the generator):
#   1. the generator: no render/refusal/vocab/api/poison/strict failure;
#   2. the run: 0 failed checks, 0 failed sites, 0 faults, and at least
#      FLOOR_GATE_SITES gate-family sites run, in the plain and the
#      sanitized build alike;
#   3. the landmark space's census (LMSITES): at least FLOOR_LM_HARD hard
#      sites, every member byte 0..255 a hard site's member, and each of the
#      15 near-miss kinds at least FLOOR_LM_NEAR sites;
#   4. REACH, through the kit's own trace (build/libpcrec_mftrace.a, built
#      first if absent): the row precheck_assign_byte chosen at least
#      FLOOR_LM_ROW times, so the hard sites are the row's and not generic's;
#   5. THE CONTROL: the same space with W2's textual mutation 2 (the rendered
#      text's first ` >= ` made ` > `: the landmark's miss test no longer
#      runs on_miss at `n`) run in --mutants mode must kill at least
#      FLOOR_KILL of the mutated sites, so a harness that stopped seeing the
#      landmark's answers is red.
# Prints `checks passed: N` / `checks failed: M`; exit 0 iff M is 0.
# Work files under $TMPDIR (required: the session scratchpad).
set -u
here=$(cd "$(dirname "$0")" && pwd)
root=$(cd "$here/../.." && pwd)
g2="$here/g2"
inc="$root/memfn/include"
lib="$root/build/libpcrec.a"
trlib="$root/build/libpcrec_mftrace.a"
seed=20261005
keep=0
while [ $# -gt 0 ]; do
    case "$1" in
        --seed) seed=$2; shift 2 ;;
        --keep) keep=1; shift ;;
        *) echo "run_g2_gate.sh: unknown option $1" >&2; exit 2 ;;
    esac
done
# measured 2026-10-11 (Linux dev box, seed 20261005, lane r15b), less ~10%:
# 806 gate sites run; 256 hard landmark sites, 16-18 per near-miss kind;
# precheck_assign_byte chosen 802 times in the generator's trace; the
# control killed 345 of 388 mutated sites (88%)
FLOOR_GATE_SITES=720
FLOOR_LM_HARD=230
FLOOR_LM_NEAR=14
FLOOR_LM_ROW=720
FLOOR_KILL=80
if command -v gnutimeout >/dev/null 2>&1; then TO=gnutimeout; else TO=timeout; fi
CC=${CC:-gcc}
[ -f "$lib" ] || { echo "run_g2_gate.sh: $lib missing (build pcrec first)" >&2; exit 2; }
if [ ! -f "$trlib" ]; then
    "$TO" 900 make -C "$root" build/libpcrec_mftrace.a >/dev/null || { echo "run_g2_gate.sh: cannot build $trlib" >&2; exit 2; }
fi
: "${TMPDIR:?run_g2_gate.sh: set TMPDIR to a scratch directory}"
work=$(mktemp -d "$TMPDIR/g2gate.XXXXXX") || exit 2
[ "$keep" = 1 ] || trap 'rm -rf "$work"' EXIT
nproc_=$(getconf _NPROCESSORS_ONLN 2>/dev/null || echo 4)
pass=0; fail=0
ok()  { pass=$((pass + 1)); }
bad() { fail=$((fail + 1)); echo "FAIL: $*"; }

# gen NAME LIB [generator flags]: the gate family alone into $work/NAME
gen() {
    local name=$1 l=$2; shift 2
    "$TO" 300 "$CC" -std=gnu11 -O1 -w -I "$inc" "$g2/g2_gen.c" "$l" -o "$work/gen-$name" || return 1
    mkdir -p "$work/$name"
    "$TO" 600 "$work/gen-$name" "$work/$name" --gate-only 1 --seed "$seed" "$@" \
        > "$work/$name.log" 2> "$work/$name.err"
}
# build NAME [cflags]: G2's driver over $work/NAME's batches
build() {
    local name=$1; shift
    local bd="$work/b-$name" gd="$work/${name%%-*}"
    mkdir -p "$bd"
    ls "$gd"/batch_*.c | "$TO" 900 xargs -P "$nproc_" -I{} sh -c \
        '"$1" -std=gnu11 -O1 -w '"$*"' -I "$2" -c "$3" -o "$4/$(basename "$3" .c).o"' \
        _ "$CC" "$g2" {} "$bd" || return 1
    for f in g2_driver g2_ref; do
        "$TO" 300 "$CC" -std=gnu11 -O1 -w "$@" -I "$g2" -c "$g2/$f.c" -o "$bd/$f.o" || return 1
    done
    "$TO" 300 "$CC" -std=gnu11 -O1 -w "$@" -I "$g2" -c "$gd/g2_all.c" -o "$bd/g2_all.o" || return 1
    "$TO" 300 "$CC" "$@" "$bd"/*.o -o "$bd/g2_run"
}
num() { grep "^G2 $2" "$1" | head -1 | sed 's/.*: *//; s/ .*//'; }

# 1. the generator (plain library), and the same sites through the trace
if ! gen gate "$lib"; then cat "$work/gate.log" "$work/gate.err"; bad "the gate-only generator failed"; fi
sum=$(grep '^SUMMARY' "$work/gate/gen_results.txt" 2>/dev/null)
gfail=0
for f in render_fail refusal_fail vocab_fail api_fail poison_fail strict_fail; do
    v=$(echo "$sum" | tr ' ' '\n' | sed -n "s/^$f=//p"); gfail=$((gfail + ${v:-1}))
done
if [ -n "$sum" ] && [ "$gfail" = 0 ]; then ok; else bad "generator stage: $gfail failure(s): grep FAIL $work/gate/gen_results.txt"; fi

# 2. the run, plain and sanitized
for leg in plain asan; do
    fl=""; [ "$leg" = asan ] && fl="-fsanitize=address,undefined -fno-omit-frame-pointer -fno-sanitize-recover=undefined"
    # shellcheck disable=SC2086
    if build "gate-$leg" $fl; then
        ASAN_OPTIONS=handle_segv=0:handle_sigbus=0:detect_leaks=0 \
            "$TO" 1800 "$work/b-gate-$leg/g2_run" $([ "$leg" = asan ] && echo --quick) \
            > "$work/run-$leg.log" 2> "$work/run-$leg.err"; rc=$?
        cf=$(num "$work/run-$leg.log" "checks failed"); sf=$(num "$work/run-$leg.log" "sites failed")
        fa=$(num "$work/run-$leg.log" "faults")
        gs=$(sed -n 's/^G2 family gate: sites \([0-9]*\) .*/\1/p' "$work/run-$leg.log")
        echo "== $leg: gate sites run ${gs:-0}, checks failed ${cf:-?}, sites failed ${sf:-?}, faults ${fa:-?} (driver rc $rc)"
        if [ "${cf:-1}" = 0 ] && [ "${sf:-1}" = 0 ] && [ "${fa:-1}" = 0 ]; then ok
        else bad "$leg: the gate family answered wrong or faulted: $work/run-$leg.log"; fi
        if [ "${gs:-0}" -ge "$FLOOR_GATE_SITES" ]; then ok
        else bad "$leg: ${gs:-0} gate sites run < floor $FLOOR_GATE_SITES (K35)"; fi
    else
        bad "$leg: the gate family's batches do not build"
    fi
done

# 3. the landmark census
lm=$(grep '^LMSITES' "$work/gate/gen_results.txt")
echo "== $lm"
hard=$(echo "$lm" | sed -n 's/.*hard=\([0-9]*\).*/\1/p')
cov=$(echo "$lm" | sed -n 's/.*members_covered=\([0-9]*\).*/\1/p')
near=$(echo "$lm" | sed -n 's/.*near=\([0-9,]*\).*/\1/p')
if [ "${hard:-0}" -ge "$FLOOR_LM_HARD" ] && [ "${cov:-0}" = 256 ]; then ok
else bad "landmark: ${hard:-0} hard sites (floor $FLOOR_LM_HARD), ${cov:-0}/256 member bytes"; fi
nk=0; low=""
for v in $(echo "$near" | tr ',' ' '); do
    nk=$((nk + 1)); [ "$v" -ge "$FLOOR_LM_NEAR" ] || low="$low $nk:$v"
done
if [ "$nk" = 15 ] && [ -z "$low" ]; then ok
else bad "landmark: near-miss kinds $nk/15, under floor $FLOOR_LM_NEAR:${low:- none}"; fi

# 4. reach: the row chosen, by the kit's own trace
if gen gatetr "$trlib"; then
    ch=$(sed -n 's/^MFTRACE REACH table=arms row=precheck_assign_byte chosen=\([0-9]*\).*/\1/p' "$work/gatetr.err" | head -1)
    echo "== precheck_assign_byte chosen ${ch:-0} (trace)"
    if [ "${ch:-0}" -ge "$FLOOR_LM_ROW" ]; then ok
    else bad "reach: precheck_assign_byte chosen ${ch:-0} < floor $FLOOR_LM_ROW: the landmark sites went to another row"; fi
else
    bad "the traced gate-only generator failed"
fi

# 5. the control: W2 mutation 2 over the same space
if gen mut2 "$lib" --mutate 2 && build "mut2-plain"; then
    "$TO" 1800 "$work/b-mut2-plain/g2_run" --quick --mutants > "$work/mut2.log" 2>/dev/null
    m=$(sed -n 's/^G2 mutants: mutated \([0-9]*\) killed \([0-9]*\).*/\1 \2/p' "$work/mut2.log")
    mm=${m%% *}; mk=${m##* }
    echo "== control (W2 mutation 2): mutated ${mm:-0}, killed ${mk:-0}"
    if [ "${mm:-0}" -gt 0 ] && [ $(( ${mk:-0} * 100 )) -ge $(( ${mm:-1} * FLOOR_KILL )) ]; then ok
    else bad "control: W2 mutation 2 killed ${mk:-0} of ${mm:-0} mutated sites (< $FLOOR_KILL%)"; fi
else
    bad "control: the mutated gate family does not generate or build"
fi

echo "checks passed: $pass"
echo "checks failed: $fail"
[ "$fail" -eq 0 ]
